UPDATE "Problem" SET "statementText"=E'$\\left\\ \\begin{array}{r} 7^{x} \\bullet 2^{x} < 196 \\\\ 3^{\\frac{x}{10}} > 9^{\\frac{5}{x}} \\end{array} \\right$ тэнцэтгэл бишийг бод.' WHERE id='cmqdbo9oe00px407npa8jccdn';
