UPDATE "Problem" SET "statementText"=E'$(x^{2} + 4x) \\bullet \\sqrt{x - 3} = 0$ тэгшитгэлийг бод.' WHERE id='cmqdboa0e00vn407n3cmbj0ys';
UPDATE "Problem" SET "statementText"=E'$x \\bullet \\sqrt[4]{x} + \\sqrt[8]{x^{5}} = 2$ тэгшитгэлийг бод. Бодолт: $x^{\\frac{\\lbrack a\\rbrack}{\\lbrack b\\rbrack}} = t, t \\geq \\lbrack c\\rbrack$ гэсэн орлуулга хийвэл $t^{2} + \\lbrack d\\rbrack t - \\lbrack e\\rbrack = 0$ гэсэн тэгшитгэлд шилжих ба эндээс $t_{1} = - \\lbrack f\\rbrack,t_{2} = \\lbrack g\\rbrack$ гэсэн шийдүүд олдоно. Орлуулгаа буцаан тэгшитгэлийн шийдийг олбол $\\lbrack h\\rbrack$ байна. $\\$' WHERE id='cmqdboa4w00xt407nbrn9t38q';
