UPDATE "Problem" SET "statementText"=E'$\\sqrt{9 \\bullet 2^{x} + 25} = 2^{x} - 3$ тэгшитгэл хэдэн шийдтэй вэ? Бодолт: $2^{x} - 3 = t;t \\geq \\lbrack a\\rbrack$ гэсэн орлуулга хийвэл $\\sqrt{\\lbrack b\\rbrack t + 5\\lbrack c\\rbrack} = t$ гэсэн тэгшитгэлд шилжих ба энэ тэгшитгэлийн шийдүүд $t_{1} = - \\lbrack d\\rbrack;t_{2} = 1\\lbrack e\\rbrack$ байна. Орлуулгаа буцаавал анхны тэгшитгэлийн шийд $x = \\lbrack f\\rbrack$ байна.' WHERE id='cmqdbo8lq00ar407nl38jxvda';
