UPDATE "Problem" SET "statementText"=E'$x,y,z$ нь эерэг бодит тоонууд ба $x \\bullet y = \\frac{3}{5}; y \\bullet z = \\frac{5}{12};z \\bullet x = \\frac{9}{4}$ бол $x,y,z$ тоонуудыг жиш. Бодолт: $x \\bullet y = \\frac{3}{5}; y \\bullet z = \\frac{5}{12}$ ба $z \\bullet x = \\frac{9}{4}$ өгөгдлүүдийг ашиглан $(x \\bullet y \\bullet z)^{2} = \\left( \\frac{\\lbrack a\\rbrack}{\\lbrack b\\rbrack} \\right)^{2}$ болно.Эндээс $x \\bullet y \\bullet z = \\pm \\frac{\\lbrack a\\rbrack}{\\lbrack b\\rbrack}$ гэдгээс эерэг бодит тоонууд учраас $x \\bullet y \\bullet z = \\frac{\\lbrack a\\rbrack}{\\lbrack b\\rbrack}$ болох ба $x,y,z$ тоонуудыг олбол $x = \\frac{\\lbrack c\\rbrack}{\\lbrack d\\rbrack},y = \\frac{1}{\\lbrack e\\rbrack},z = \\frac{\\lbrack f\\rbrack}{\\lbrack g\\rbrack}$ болно. Иймд бидний олох хариулт $x > z > y$ гэж олдоно.' WHERE id='cmqdboev2038n407ngczwz2cq';
