UPDATE "Problem" SET "statementText"=E'$\\sin{3x} \\bullet \\cos{3x} \\bullet \\cos{6x} = \\frac{\\sqrt{3}}{8}$ тэгшитгэлийн $\\lbrack 0;45{^\\circ}\\rbrack$ завсар дахь шийдүүдийн нийлбэрийг ол. Бодолт: $\\sin{3x} \\bullet \\cos{3x} \\bullet \\cos{6x} = \\frac{\\sqrt{3}}{8} \\rightarrow \\sin\\left( \\overline{1\\lbrack a\\rbrack}x \\right) = \\frac{\\sqrt{3}}{\\lbrack b\\rbrack}$ болох ба цааш бодвол уг тэгшитгэлийн шийд $x = ( - 1)^{k}\\frac{\\pi}{\\lbrack cd\\rbrack} + \\frac{\\pi k}{1\\lbrack e\\rbrack} (k\\epsilon Z)$ байна. Иймд бидний олох $x\\epsilon\\lbrack 0;45{^\\circ}\\rbrack$ завсар дахь шийдүүдийн нийлбэр $\\frac{\\lbrack f\\rbrack\\pi}{\\lbrack g\\rbrack}$ байна.' WHERE id='cmrawe4f905xvyy7nqqcuflwb';
UPDATE "Problem" SET "statementText"=E'$\\tg^{2}x - \\left( 1 + \\sqrt{3} \\right) \\bullet tgx + \\sqrt{3} = 0$ тэгшитгэлийг бод.' WHERE id='cmrawe4g705zcyy7n5ou334tt';
UPDATE "Problem" SET "statementText"=E'$6\\sin^{2}x - sinx \\bullet cosx - \\cos^{2}x = 3$ тэгшитгэлийн $\\lbrack - \\pi;\\pi\\rbrack$ завсарт хэдэн шийдтэй вэ? Бодолт: $6\\sin^{2}x - sinx \\bullet cosx - \\cos^{2}x = 3 \\rightarrow \\lbrack a\\rbrack\\sin^{2}x - sinx \\bullet cosx - \\lbrack b\\rbrack\\cos^{2}x = 0$ болгож хувиргаад тэгшитгэлийн хоёр талыг $\\cos^{2}x \\neq \\lbrack c\\rbrack$ хувааж $tgx = t$ гэсэн орлуулга хийж цааш бодож орлуулгаа буцаавал $\\left\\lbrack \\begin{matrix} tgx = - \\lbrack d\\rbrack \\\\ tgx = \\frac{\\lbrack e\\rbrack}{\\lbrack f\\rbrack} \\end{matrix}$ тэгшитгэлд $\\right$ шилжинэ. Иймд уг тэгшитгэл өгөгдсөн завсарт $\\lbrack g\\rbrack$ ширхэг шийдтэй байна.' WHERE id='cmrawe4gd05zoyy7npmd4ggcr';
UPDATE "Problem" SET "statementText"=E'$\\tg^{2}x + tgx \\bullet \\left( \\sqrt{3} - 1 \\right) - \\sqrt{3} = 0$ тэгшитгэлийг бод.' WHERE id='cmrawe4hk0612yy7nn8vk0o74';
UPDATE "Problem" SET "statementText"=E'$5\\cos^{2}x - 3sinx \\bullet cosx + \\sin^{2}x = 3$ тэгшитгэлийн $\\lbrack - \\pi;\\pi\\rbrack$ завсарт хэдэн шийдтэй вэ? Бодолт: ${5\\cos^{2}}x - 3sinx \\bullet cosx + \\sin^{2}x = 3 \\rightarrow \\lbrack a\\rbrack{\\cos}^{2}x - sinx \\bullet cosx - \\lbrack b\\rbrack{\\sin}^{2}x = 0$ болгож хувиргаад тэгшитгэлийн хоёр талыг $\\sin^{2}x \\neq \\lbrack c\\rbrack$ хувааж $ctgx = t$ гэсэн орлуулга хийж цааш бодож орлуулгаа буцаавал $\\left\\lbrack \\begin{matrix} ctgx = \\lbrack d\\rbrack \\\\ ctgx = - \\frac{\\lbrack e\\rbrack}{\\lbrack f\\rbrack} \\end{matrix}$ тэгшитгэлд $\\right$ шилжинэ. Иймд уг тэгшитгэл өгөгдсөн завсарт $\\lbrack g\\rbrack$ ширхэг шийдтэй байна.' WHERE id='cmrawe4ig061eyy7nqzvf7krr';
UPDATE "Problem" SET "statementText"=E'$(sinx - cosx) - 4sinx \\bullet cosx = 1$ тэгшитгэлийн $\\lbrack 0;\\pi\\rbrack$ завсар дахь шийдийг ол. Бодолт: $sinx - cosx = t$ гэж орлуулга хийвэл $\\lbrack a\\rbrack t^{2} + \\lbrack b\\rbrack t - 3 = 0$ тэгшитгэлд шилжих ба цааш бодож $t -$ г олж орлуулгаа буцаавал $sinx - cosx = \\lbrack c\\rbrack$ хэлбэрт шилжинэ. $sinx - cosx = \\lbrack c\\rbrack$ тэгшитгэлийг туслах өнцгийн арга ашиглан хувиргавал $\\sin\\left( x - \\lbrack de\\rbrack{^\\circ} \\right) = \\frac{\\sqrt{\\lbrack f\\rbrack}}{2}$ болж хувирна. Иймд бидний олох шийдүүд $x = \\pi;x = \\frac{\\pi}{\\lbrack g\\rbrack}$ байна.' WHERE id='cmrawe4ij061fyy7naazyklcl';
